function normalizeOrder(order) {
  const number = order?.order_number;
  const externalId = String(number);
  if (
    (typeof number !== "string" && typeof number !== "number") ||
    !/^[1-9]\d{0,19}$/.test(externalId) ||
    (typeof number === "number" && !Number.isSafeInteger(number)) ||
    !Array.isArray(order.line_items)
  ) {
    throw new Error("Shopify order number or line items are missing or invalid");
  }

  const customer = order.customer;
  const customerName = [customer?.first_name, customer?.last_name]
    .filter((part) => typeof part === "string" && part.trim())
    .join(" ");
  const email = [customer?.email, order.contact_email, order.email].find(
    (value) => typeof value === "string" && value.trim(),
  );
  const subject = "Order #" + externalId + " - " + order.line_items.length + " item(s)";
  return {
    externalId,
    subject,
    comment: {
      body: [
        subject,
        "",
        "Order:",
        "Customer: " + (customerName || "Unavailable"),
        "email: " + (email || "Unavailable"),
        "Status: New order",
      ].join("\n"),
    },
    status: "open",
  };
}
return $input.all().map(({ json }) => ({ json: normalizeOrder(json) }));

function readPage(body, externalId, state) {
  const { tickets, meta } = body ?? {};
  if (!Array.isArray(tickets) || typeof meta?.has_more !== "boolean") {
    throw new Error("Zendesk returned an invalid ticket page");
  }

  const nextCursor = meta.has_more ? meta.after_cursor : null;
  if (
    meta.has_more &&
    (typeof nextCursor !== "string" || !nextCursor || state.cursors.includes(nextCursor))
  ) {
    throw new Error("Zendesk returned an invalid pagination cursor");
  }

  let latestId = state.latestId;
  let open = state.open;
  for (const ticket of tickets) {
    if (typeof ticket?.external_id !== "string") {
      throw new Error("Zendesk returned a ticket with no external ID");
    }
    if (ticket.external_id !== externalId) continue;
    if (!Number.isSafeInteger(ticket.id) || ticket.id < 1 || typeof ticket.status !== "string") {
      throw new Error("Zendesk returned an invalid matching ticket");
    }
    latestId = Math.max(ticket.id, latestId);
    open ||= ticket.status === "open";
  }

  return {
    cursors: nextCursor ? [...state.cursors, nextCursor] : state.cursors,
    latestId,
    open,
  };
}

function ticketKey(externalId, latestId) {
  return "shopify-order-" + externalId + "-after-zendesk-" + latestId;
}
const { externalId, ...ticketFields } = $("Read order number").first().json;
let state = { cursors: [], latestId: 0, open: false };
const pages = $input.all();
if (!pages.length) throw new Error("Zendesk returned no ticket pages");
for (const [index, { json }] of pages.entries()) {
  if (json.statusCode !== 200) throw new Error("Zendesk ticket lookup failed");
  state = readPage(json.body, externalId, state);
  if (json.body.meta.has_more !== index < pages.length - 1) {
    throw new Error("Zendesk ticket lookup did not return a complete page sequence");
  }
}
return state.open
  ? []
  : [
      {
        json: {
          externalId,
          body: { ticket: { ...ticketFields, external_id: externalId } },
          key: ticketKey(externalId, state.latestId),
        },
      },
    ];

function confirm({ response, statusCode, externalId }) {
  const ticket = response?.ticket;
  if (
    statusCode !== 201 ||
    !Number.isSafeInteger(ticket?.id) ||
    ticket.id < 1 ||
    ticket.external_id !== externalId
  ) {
    throw new Error("Zendesk did not confirm the new ticket for this order");
  }
  return { ticketId: ticket.id };
}

const externalId = $("Check for an open ticket").first().json.externalId;
return $input.all().map(({ json }) => ({
  json: confirm({ response: json.body, statusCode: json.statusCode, externalId }),
}));
